// Replay deterministic traces generated by the actual read-only upstream classes.
use std::{cell::RefCell, rc::Rc};
use xterm_core::{
    buffer::{AttributeData, Buffer, BufferService},
    options::{OptionValue, OptionsService},
};

fn units(text: &[u16]) -> String {
    if text.is_empty() {
        "-".into()
    } else {
        text.iter()
            .map(|unit| format!("{unit:x}"))
            .collect::<Vec<_>>()
            .join(",")
    }
}
fn buffer_snapshot(buffer: &Buffer) -> String {
    let mut rows = Vec::new();
    for row in 0..buffer.lines.len() {
        let line = buffer.lines.get(row).expect("trace contains dense lines");
        let line = line.borrow();
        let mut cells = Vec::new();
        for col in 0..line.len() {
            let cell = line
                .get_cell(col)
                .expect("trace has no unresolved extended cells");
            cells.push(format!(
                "{}:{}:{}:{}",
                cell.content,
                cell.fg,
                cell.bg,
                units(&cell.get_chars())
            ));
        }
        rows.push(format!("{};{}", u8::from(line.is_wrapped), cells.join("/")));
    }
    let tabs = buffer
        .tabs
        .iter()
        .map(usize::to_string)
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{}~{}~{}~{}~{}~{}~{}~{}~{}~{}~{}",
        buffer.x,
        buffer.y,
        buffer.ybase,
        buffer.ydisp,
        buffer.scroll_top,
        buffer.scroll_bottom,
        buffer.lines.len(),
        buffer.lines.max_length(),
        u8::from(buffer.has_scrollback()),
        tabs,
        rows.join("|")
    )
}
#[test]
fn all_seeded_buffer_set_and_service_operations_match_javascript() {
    let fixture = include_str!("fixtures/buffer-service.tsv");
    assert_eq!(fixture.lines().count(), 4096);
    let mut current = usize::MAX;
    let mut session: Option<(BufferService, Rc<OptionsService>)> = None;
    let events = Rc::new(RefCell::new(Vec::new()));
    for line in fixture.lines() {
        let p: Vec<_> = line.split('\t').collect();
        assert_eq!(p.len(), 14);
        let trace: usize = p[0].parse().unwrap();
        if trace != current {
            let options = Rc::new(OptionsService::new(
                false,
                [
                    ("cols", OptionValue::Number(10.0)),
                    ("rows", OptionValue::Number(5.0)),
                    ("scrollback", OptionValue::Number(4.0)),
                ],
            ));
            let service = BufferService::new(Rc::clone(&options)).unwrap();
            let seen = Rc::clone(&events);
            service
                .on_scroll()
                .subscribe(move |value| seen.borrow_mut().push(format!("s,{value}")));
            let seen = Rc::clone(&events);
            service.on_resize().subscribe(move |e| {
                seen.borrow_mut().push(format!(
                    "r,{},{},{},{}",
                    e.cols,
                    e.rows,
                    u8::from(e.cols_changed),
                    u8::from(e.rows_changed)
                ))
            });
            let seen = Rc::clone(&events);
            let buffers = Rc::downgrade(&service.buffers);
            service.buffers.on_buffer_activate().subscribe(move |e| {
                let buffers = buffers.upgrade().unwrap();
                seen.borrow_mut().push(format!(
                    "a,{}",
                    if Rc::ptr_eq(&e.active_buffer, &buffers.normal()) {
                        "n"
                    } else {
                        "a"
                    }
                ));
            });
            session = Some((service, options));
            current = trace;
        }
        events.borrow_mut().clear();
        let (service, options) = session.as_ref().unwrap();
        let a: i64 = p[3].parse().unwrap();
        let b: usize = p[4].parse().unwrap();
        let attr = AttributeData {
            fg: p[6].parse().unwrap(),
            bg: p[5].parse().unwrap(),
            ..AttributeData::default()
        };
        match p[2] {
            "scroll" => service.scroll(&attr, a != 0).unwrap(),
            "display" => service.scroll_lines(a, b != 0).unwrap(),
            "margins" => {
                let active = service.buffer();
                let mut active = active.borrow_mut();
                active.scroll_top = a as usize;
                active.scroll_bottom = b;
            }
            "cursor" => {
                let active = service.buffer();
                let mut active = active.borrow_mut();
                active.x = a as usize;
                active.y = b;
            }
            "alt" => service.buffers.activate_alt_buffer(Some(&attr)).unwrap(),
            "normal" => service.buffers.activate_normal_buffer().unwrap(),
            "resize" => service.resize(a as usize, b).unwrap(),
            "reset" => service.reset().unwrap(),
            "scrollback" => options
                .set("scrollback", OptionValue::Number(a as f64))
                .unwrap(),
            "tabs" => options
                .set("tabStopWidth", OptionValue::Number(a as f64))
                .unwrap(),
            "write" => {
                let active = service.buffer();
                let active = active.borrow();
                active
                    .lines
                    .get(active.ybase + a as usize)
                    .unwrap()
                    .borrow_mut()
                    .set_cell_from_codepoint(0, b as u32, 1, &attr);
            }
            "user" => service.is_user_scrolling.set(a != 0),
            _ => panic!("unknown generated operation"),
        }
        let expected = p[7..].join("\t");
        let emitted = if events.borrow().is_empty() {
            "-".into()
        } else {
            events.borrow().join("|")
        };
        let actual = format!(
            "{}\t{}\t{}\t{}\t{}\t{}\t{}",
            service.cols(),
            service.rows(),
            u8::from(service.is_user_scrolling.get()),
            if Rc::ptr_eq(&service.buffer(), &service.buffers.normal()) {
                "n"
            } else {
                "a"
            },
            buffer_snapshot(&service.buffers.normal().borrow()),
            buffer_snapshot(&service.buffers.alt().borrow()),
            emitted
        );
        assert_eq!(
            actual, expected,
            "trace{} step{} op{} seed0x5e7b0ff",
            p[0], p[1], p[2]
        );
    }
}
